function load(){try{const v=JSON.parse(localStorage.getItem(APP_KEY)||'null');if(v && typeof v==='object' && v.profile && I[v.lang])return {...blank(),...v,cvLang:I[v.cvLang]?v.cvLang:null,profile:{...blank().profile,...v.profile},meta:{...blank().meta,...v.meta}};}catch{}return blank()}
