function readChatDraft(){try{return (sessionStorage.getItem('careerbrand-chat-draft')||'').slice(0,4000)}catch{return ''}}
function updateChatDraft(value){
 chatDraft=value.slice(0,4000);
 try{
  if(chatDraft)sessionStorage.setItem('careerbrand-chat-draft',chatDraft);
  else sessionStorage.removeItem('careerbrand-chat-draft');
 }catch{}
}
let S=load(),chatDraft=readChatDraft(),aiProvider='openai',apiReady=false,jobsReady=false,demoProtected=false,accessCode=readDemoCode(),aiProbe=null,aiProbeBusy=false,chatBusy=false,marketBusy=false,agentBusy=false,cvReviewBusy=false,cvReview=null,cvReviewConsent=false,marketError='',editingProjectId=-1,diagnosticBusy=false,serviceCheck=null;
let cvDraft=null,draftConsent=false,draftReview=false,draftBusy=false,draftError='',draftRequest=null,draftLang=null;
let chatRequest=null,pendingChat=null,failedChat=null;
const draftReplacements=new Set();
const root=document.getElementById('app');
const tr=k=>(I[S.lang][k]??I.kk[k]??k);
const cvTr=k=>(I[S.cvLang||S.lang]?.[k]??I.kk[k]??k);
const esc=x=>String(x??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const fmt=(k,values={})=>tr(k).replace(/\{([a-zA-Z]+)\}/g,(_,key)=>String(values[key]??''));
const nl=x=>esc(x).replace(/\n/g,'<br>');
const save=()=>{try{localStorage.setItem(APP_KEY,JSON.stringify({...S,messages:S.messages.slice(-20),market:null}));}catch{}};
const skills=()=>S.profile.skills.split(/[,;\n]/).map(v=>v.trim()).filter(Boolean);
const completed=()=>{const p=S.profile;return Math.round([p.name,p.role,p.city,p.email,p.summary.length>=80?p.summary:'',p.education,p.experience,skills().length>=3?'yes':'',p.achievements].filter(Boolean).length/9*100)};
const pitem=(x)=>'<span class="pill">'+esc(x)+'</span>';
const icon={overview:'⌂',brand:'✧',resume:'▤',portfolio:'▦',video:'▷',market:'▥',assistant:'✦',media:'◇',research:'◫'};
const NAV_SVG={
 overview:'<rect x="3" y="3" width="8" height="8" rx="2"/><rect x="13" y="3" width="8" height="5" rx="2"/><rect x="13" y="10" width="8" height="11" rx="2"/><rect x="3" y="13" width="8" height="8" rx="2"/>',
 brand:'<path d="m12 3 1.5 5.5L19 10l-5.5 1.5L12 17l-1.5-5.5L5 10l5.5-1.5L12 3Z"/><path d="m19 17 .7 1.5L21 19l-1.3.5L19 21l-.7-1.5L17 19l1.3-.5L19 17Z"/>',
 resume:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>',
 portfolio:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18M10 12v2h4v-2"/>',
 video:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m10 9 5 3-5 3V9Z"/>',
 market:'<path d="M4 19V5M4 19h16M8 15l4-5 3 2 4-6"/><path d="M16 6h3v3"/>',
 assistant:'<rect x="4" y="7" width="16" height="14" rx="3"/><path d="M12 3v4M8 13h.01M16 13h.01M8 17h8"/>',
 research:'<circle cx="11" cy="11" r="7"/><path d="m16.3 16.3 4.2 4.2M8 11h6M11 8v6"/>',
 media:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1"/><path d="m3 17 6-6 4 4 3-3 5 5"/>'};
const navIcon=k=>`<svg class="line-icon" viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${NAV_SVG[k]||NAV_SVG.overview}</svg>`;
function readTheme(){try{return localStorage.getItem('careerbrand-theme-v7')==='light'?'light':'dark'}catch{return'dark'}}
let theme=readTheme();
function applyTheme(){if(typeof document==='undefined'||!document.documentElement)return;const el=document.documentElement;if(el.dataset)el.dataset.theme=theme;if(el.style)el.style.colorScheme=theme==='light'?'light':'dark'}
applyTheme();

function template(k){return `<div class="section-header"><div class="eyebrow">${tr(k+'Eyebrow')===''+k+'Eyebrow'?'':tr(k+'Eyebrow')}</div><h1>${tr(k+'Title')}</h1><p class="subtle">${tr(k+'Sub')}</p></div>`}
function pageHeader(k){return `<div class="section-header"><div class="eyebrow">${tr(k+'Eyebrow')}</div><h1>${tr(k+'Title')}</h1><p class="subtle">${tr(k+'Sub')}</p></div>`}
function field(key,label,placeholder='',multi=false){let value=esc(S.profile[key]);return `<div class="field"><label for="field-${key}">${tr(label)}</label>${multi?`<textarea rows="3" id="field-${key}" data-field="${key}" placeholder="${esc(tr(placeholder))}">${value}</textarea>`:`<input id="field-${key}" data-field="${key}" value="${value}" placeholder="${esc(tr(placeholder))}">`}</div>`}
function shell(){
 document.title=tr('siteTitle');
 document.documentElement.lang=S.lang;
 applyTheme();
 const navs=['overview','brand','resume','portfolio','video','market','assistant','research','media'];
 root.innerHTML=`<a href="#content" class="skip-link">${tr('dashSkip')}</a><div class="app-shell"><aside class="side"><div class="brand"><div class="brand-icon"><span>✧</span></div><div><div class="brand-name">careerbrand<span class="brand-dot">.</span><b>ai</b></div><div class="brand-sub">${tr('dashLabel')}</div></div></div><div class="nav-caption">${tr('navTitle')}</div><nav class="nav" aria-label="${tr('dashMobileNav')}">${navs.map(n=>`<button type="button" class="nav-link ${S.page===n?'active':''}" data-page="${n}" ${S.page===n?'aria-current="page"':''}><span class="nav-ico">${navIcon(n)}</span><span>${tr(n)}</span>${S.page===n?'<i class="nav-indicator" aria-hidden="true"></i>':''}</button>`).join('')}</nav><div class="side-divider"></div><div class="side-info"><span class="side-info-indicator"></span><div><strong>CareerBrand AI <small>v9.0</small></strong><p>${tr('menuHelp')}</p></div></div></aside><div class="workspace"><header class="topbar"><div class="topbar-left"><div class="top-eyebrow">WORKSPACE <span class="slash">/</span> <b>${tr(S.page)}</b></div><div class="topbar-subtitle">${tr('dashLabel')}</div></div><div class="top-actions"><span class="mode"><span class="mode-dot"></span>${tr('demo')}</span><button class="theme-toggle" type="button" data-action="toggle-theme" aria-label="${tr('dashTheme')}" title="${tr('dashTheme')}">${theme==='dark'?'☼':'☾'}</button><select id="language" class="language-picker" aria-label="Language"><option value="kk" ${S.lang==='kk'?'selected':''}>🇰🇿 Қазақша</option><option value="ru" ${S.lang==='ru'?'selected':''}>🇷🇺 Русский</option><option value="en" ${S.lang==='en'?'selected':''}>🇬🇧 English</option></select><div class="user-bubble" aria-hidden="true">${esc((S.profile.name.trim()[0]||'A').toUpperCase())}</div></div></header><main class="container" id="content" tabindex="-1"></main><button type="button" class="assistant-fab" data-page="assistant" title="${tr('assistant')}" aria-label="${tr('assistant')}">✦ <span>${tr('assistant')}</span></button></div></div>`;
 renderPage();
}

const foot=()=>`<footer class="footer"><strong>CareerBrand AI</strong> · Нархоз университеті · ${esc(S.meta.school||tr('authorPlaceholder'))}<br>${tr('subject')} · ${esc(S.meta.major||tr('authorPlaceholder'))} · ${esc(S.meta.name||tr('authorPlaceholder'))} · © 2026<br><span>${tr('storage')}</span></footer>`;
function overview(){
 const p=S.profile;
 const skillCount=skills().length;
 const profileReady=completed()>=67;
 const projectsReady=S.projects.length>0;
 const marketReady=Boolean(S.market?.vacancies?.length);
 const fullName=p.name.trim().split(/\s+/)[0];
 const navs=[['brand','dashFeatureBrand'],['resume','dashFeatureResume'],['portfolio','dashFeaturePortfolio'],['market','dashFeatureMarket'],['assistant','dashAssistantCard'],['video','featureVideo']];
 const milestones=[
 {title:tr('dashProfile'),done:profileReady,note:tr('dashProgress')+' · '+completed()+'%'},
 {title:tr('dashEvidence'),done:projectsReady,note:tr('dashProjects')+' · '+S.projects.length},
 {title:tr('dashMarket'),done:marketReady,note:marketReady?tr('dashSet'):tr('dashNotConnected')}
 ];
 const dashboardLabel=fullName?`${tr('dashWelcome')}, ${esc(fullName)}`:tr('dashGreeting');
 const circle=completed();
 return `<div class="dashboard page-enter">
 <div class="dashboard-intro"><div><div class="eyebrow"><span class="eyebrow-mark"></span>${tr('dashLabel')}</div><h1>${dashboardLabel}</h1><p class="subtle">${tr('homeSub')}</p></div><span class="intro-version">CB / 09.0 <span class="diamond">✧</span></span></div>
 ${accessPanel()}
 <section class="command-hero"><div class="hero-main"><div class="hero-kicker"><span class="kicker-dot"></span> CAREER INTELLIGENCE · v13.0</div><h2>${tr('dashHeroTitle')}</h2><p>${tr('dashHeroDesc')}</p><div class="hero-buttons"><button type="button" class="btn hero-primary" data-page="resume">${tr('dashStart')} <span>↗</span></button><button type="button" class="btn hero-secondary" data-page="assistant">✧ ${tr('dashAsk')}</button></div><div class="hero-disclaimer">◈ ${tr('dashMockNote')}</div></div>
 <div class="hero-visual"><div class="constellation-grid"></div><div class="visual-head"><span class="visual-mark">✦</span><span>PROFILE INTELLIGENCE</span><span class="tiny-index">001 / LIVE LOCAL</span></div><div class="visual-center"><div class="donut" style="--progress:${circle}"><div><strong>${circle}<small>%</small></strong><span>${tr('dashProgress')}</span></div></div><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div></div><div class="visual-foot"><span><i class="status-indicator"></i>${tr('dashFilling')}</span><span>${String(skillCount).padStart(2,'0')} SKILLS</span></div></div></section>
 <div class="metric-grid"><div class="metric-card"><div class="metric-head"><span>01 / ${tr('dashProgress')}</span>${navIcon('resume')}</div><div class="metric-value">${completed()}<small>%</small></div><div class="meter metric-track"><span style="width:${completed()}%"></span></div><div class="metric-note">${tr('dashFilling')}</div></div><div class="metric-card"><div class="metric-head"><span>02 / ${tr('dashProjects')}</span>${navIcon('portfolio')}</div><div class="metric-value">${String(S.projects.length).padStart(2,'0')}</div><div class="metric-note">${projectsReady?tr('dashSet'):tr('dashEmpty')}</div></div><div class="metric-card"><div class="metric-head"><span>03 / ${tr('dashSkills')}</span>${navIcon('brand')}</div><div class="metric-value">${String(skillCount).padStart(2,'0')}</div><div class="metric-note">${tr('dashStatusNote')}</div></div></div>
 <div class="section-row section-row-lg"><div><div class="eyebrow">YOUR WORKSPACE</div><h2>${tr('dashModuleTitle')}</h2><p class="subtle">${tr('dashModuleDesc')}</p></div><button class="link-action" data-page="brand">${tr('dashExplore')} <span>↗</span></button></div>
 <div class="module-grid">${navs.map(([k,d],i)=>`<button type="button" class="module-card module-${k}" data-page="${k}"><div class="module-top"><span class="module-icon">${navIcon(k)}</span><span class="module-index">0${i+1}</span></div><div class="module-bottom"><h3>${tr(k)}</h3><p>${tr(d)}</p><span class="module-arrow">↗</span></div></button>`).join('')}</div>
 <div class="insight-grid"><section class="insight-card"><div class="insight-heading"><div><div class="eyebrow">YOUR NEXT STEPS</div><h2>${tr('dashRoadmap')}</h2><p class="subtle">${tr('dashRoadmapSub')}</p></div><span class="insight-deco">◉</span></div><div class="timeline">${[1,2,3].map((n,i)=>`<div class="timeline-row"><div class="timeline-step ${milestones[i].done?'done':''}">${milestones[i].done?'✓':String(n).padStart(2,'0')}</div><div class="timeline-copy"><h3>${tr('step'+n)}</h3><p>${tr('step'+n+'sub')}</p></div><span class="timeline-arrow" aria-hidden="true">→</span></div>`).join('')}</div></section><section class="insight-card current-state"><div class="eyebrow">STATUS PANEL</div><h2>${tr('dashYourStatus')}</h2><p class="subtle">${tr('dashStatusNote')}</p><div class="status-list">${milestones.map((m,i)=>`<div class="status-item"><span class="status-circle ${m.done?'good':''}">${m.done?'✓':'·'}</span><div><strong>${m.title}</strong><small>${m.note}</small></div><span class="status-chevron">↗</span></div>`).join('')}</div><div class="system-note"><span class="system-spark">✧</span><div><b>${tr('dashAIState')}</b><p>${apiReady?tr('dashAIConfigured'):tr('dashAINotConfigured')}</p></div></div></section></div>
 <div class="section-row section-row-lg settings-heading"><div><div class="eyebrow">TOOLS & DATA</div><h2>${tr('dashSetup')}</h2></div></div>
 <div class="grid" style="align-items:start"><section class="card"><h2>${tr('diagnosticsTitle')}</h2><p class="subtle" style="margin:9px 0 15px">${tr('diagnosticsDesc')}</p><div id="diagnostic-output">${diagnosticMarkup()}</div><button class="btn soft" data-action="check-services" ${diagnosticBusy?'disabled':''}>${diagnosticBusy?tr('diagLoading'):tr('diagnosticsRun')}</button><p class="hint" style="margin-top:10px">${tr('diagNote')}</p></section><section class="card"><h2>${tr('backupTitle')}</h2><p class="subtle" style="margin:9px 0 15px">${tr('backupDesc')}</p><div class="btn-row"><button class="btn soft" data-action="export-backup">↓ ${tr('backupExport')}</button><button class="btn outline" data-action="import-backup">↑ ${tr('backupImport')}</button></div><input type="file" id="backup-file" accept="application/json,.json" hidden><p class="hint" style="margin-top:12px">${tr('backupPrivate')}</p></section></div>
 <div class="demo-tools"><div class="btn-row"><button class="btn outline small" data-action="demo">${tr('sample')}</button><button class="btn warn small" data-action="reset">${tr('reset')}</button></div></div>${S.demoActive?`<div class="notice warning">${tr('demoWarning')}</div>`:''}<section class="card defense-ready" style="margin-top:18px"><div class="section-row"><h2>${tr('defenseTitle')}</h2><span class="state">MVP v11</span></div><div class="readiness-grid"><div><b>${tr('defenseAiConfigured')}</b><span>${apiReady?tr('defenseConfigured'):tr('defenseNotReady')}</span></div><div><b>${tr('defenseJobsConfigured')}</b><span>${jobsReady?tr('defenseConfigured'):tr('defenseNotReady')}</span></div><div><b>${tr('defenseProfile')}</b><span>${completed()}%</span></div><div><b>${tr('defenseMultimedia')}</b><span>${tr('defenseReady')}</span></div></div><p class="hint" style="margin-top:13px">${tr('defenseFlow')}</p><p class="hint" style="margin-top:8px">${tr('defenseNoFake')}</p></section>${foot()}</div>`;
}

function brandStatement(){const p=S.profile;if(!p.role&&!p.goal&&!p.value)return tr('emptyProfile');return fmt('brandDefault',{role:p.role||'…',strengths:p.strengths||'…',audience:p.audience||'…',value:p.value||'…',goal:p.goal||'…'})}
function brand(){return pageHeader('brand')+`<div class="grid"><section class="card"><h2 style="margin-bottom:19px">${tr('brandTitle')}</h2>${field('goal','target','targetPlaceholder',true)}${field('strengths','strengths','strengthsPlaceholder',true)}${field('audience','audience','audiencePlaceholder')}${field('value','value','valuePlaceholder',true)}</section><section class="card"><h2>${tr('position')}</h2><div id="brand-text" class="brand-quote">${esc(brandStatement())}</div><p class="subtle">${tr('brandDisclaimer')}</p><button class="btn soft" data-action="copy-brand" style="margin-top:17px">${tr('copy')}</button><hr class="divider"><h2>${tr('roadmap')}</h2><div class="steps" style="margin-top:11px">${[1,2,3,4].map(n=>`<div class="step"><span class="step-num">${n}</span><div><h3>${tr('week'+n)}</h3><p>${tr('week'+n+'desc')}</p></div></div>`).join('')}</div></section></div>${foot()}`}
function cvPaper(){
 const p=S.profile;
 const section=(label,value)=>value?`<h4>${cvTr(label)}</h4><p>${nl(value)}</p>`:'';
 const tags=skills();
 return `<div class="cv-name">${esc(p.name||cvTr('name'))}</div>
  <div class="cv-job">${esc(p.role||cvTr('role'))}</div>
  <div class="cv-meta">${esc([p.city,p.email,p.phone].filter(Boolean).join(' · '))}</div>
  <div class="cv-line"></div>${section('about',p.summary)}
  ${tags.length?`<h4>${cvTr('skillsHead')}</h4><div>${tags.map(pitem).join('')}</div>`:''}
  ${section('eduHead',p.education)}${section('expHead',p.experience)}
  ${section('cvProjects',p.cvProjects)}${section('achHead',p.achievements)}
  ${section('cvLanguages',p.languages)}`;
}
function resume(){return pageHeader('cv')+`${S.demoActive?`<div class="notice warning" style="margin-bottom:16px">${tr('demoWarning')}</div>`:''}<div class="grid" style="align-items:start"><section class="card"><h2 style="margin-bottom:18px">${tr('personal')}</h2><div class="fieldrow">${field('name','name')}${field('role','role','exampleRole')}${field('city','city','exampleCity')}${field('email','email')}${field('phone','cvPhone')}</div>${field('summary','summary','exampleAbout',true)}${field('skills','skills','exampleSkills')}${field('education','education','exampleEdu',true)}${field('experience','experience','exampleExp',true)}${field('cvProjects','cvProjects','',true)}${field('languages','cvLanguages','',true)}${field('achievements','achievements','exampleResult',true)}<div class="meter"><span class="completion-bar" style="width:${completed()}%"></span></div><p class="hint" id="cv-completion">${tr('completion')}: ${completed()}%</p></section><section class="card"><div class="cv-preview-title"><h2>${tr('preview')}</h2><button class="btn soft small" data-action="print">↗ ${tr('pdf')}</button></div><div class="field" style="margin:12px 0"><label for="cv-lang">${tr('cvDocumentLang')}</label><select id="cv-lang">${[['kk','🇰🇿 Қазақша'],['ru','🇷🇺 Русский'],['en','🇬🇧 English']].map(([l,label])=>`<option value="${l}" ${S.cvLang===l||(!S.cvLang&&S.lang===l)?'selected':''}>${label}</option>`).join('')}</select></div><div class="cv-paper" id="cv-paper">${cvPaper()}</div><p class="hint" style="margin-top:11px">${tr('printNote')}</p></section></div><div class="notice" style="margin-top:16px">${tr('privacy')}</div>${foot()}`}
function portfolio(){const p=S.profile;const projects=S.projects.map((x,i)=>`<div class="project"><div class="ico">▦</div><h3>${esc(x.name)}</h3><p class="subtle">${nl(x.desc)}</p>${x.link&&/^https?:\/\//i.test(x.link)?`<a href="${esc(x.link)}" rel="noopener noreferrer" target="_blank">${esc(x.link)}</a>`:''}<div><button class="btn soft small" data-action="edit-project" data-id="${i}">${tr('projectEdit')}</button> <button class="btn warn small" data-action="remove-project" data-id="${i}">${tr('delete')}</button></div></div>`).join('');return pageHeader('portfolio')+`<div class="card"><div class="profile-cover"><div class="profile-avatar">${esc((p.name[0]||'A').toUpperCase())}</div><div><h2>${esc(p.name||tr('name'))}</h2><p class="subtle">${esc([p.role,p.city].filter(Boolean).join(' · '))}</p></div></div><p class="subtle" style="margin-top:17px">${esc(p.summary||tr('missing'))}</p><div style="margin-top:11px">${skills().map(pitem).join('')}</div></div><div class="section-row"><h2>${tr('myProjects')}</h2><span class="state">${S.projects.length}</span></div>${S.projects.length?`<div class="grid">${projects}</div>`:`<div class="empty"><div class="empty-icon">▦</div><h3>${tr('projectEmpty')}</h3></div>`}<section class="card" style="margin-top:17px"><h2 style="margin-bottom:16px">${tr('addProject')}</h2><div class="fieldrow"><div class="field"><label for="project-name">${tr('projectName')}</label><input id="project-name" placeholder="${tr('projectNameExample')}"></div><div class="field"><label for="project-link">${tr('projectLink')}</label><input id="project-link" type="url" placeholder="https://..."></div></div><div class="field"><label for="project-desc">${tr('projectDesc')}</label><textarea id="project-desc" placeholder="${tr('projectDescExample')}"></textarea></div><button class="btn" data-action="add-project">${editingProjectId>=0?tr('projectSave'):'+'+tr('addProject')}</button>${editingProjectId>=0?`<p class="hint" style="margin-top:8px">${tr('projectEditHint')}</p>`:''}</section>${foot()}`}
function videoScript(){const p=S.profile;const lines=[fmt('scriptHello',{name:p.name||'…'})];if(p.role)lines.push(fmt('scriptJob',{role:p.role}));if(p.summary)lines.push(fmt('scriptAbout',{summary:p.summary}));if(skills().length)lines.push(fmt('scriptSkills',{skills:skills().join(', ')}));if(p.experience)lines.push(fmt('scriptProject',{experience:p.experience}));if(p.achievements)lines.push(fmt('scriptAch',{achievements:p.achievements}));lines.push(fmt('scriptEnd',{goal:p.goal||'…'}));return lines.join('\n\n')}
function video(){return pageHeader('video')+`<div class="grid" style="align-items:start"><div class="card"><h2>${tr('script')}</h2><p class="subtle" style="margin:8px 0 15px">${tr('template')}</p><div class="script" id="video-script">${esc(videoScript())}</div><div class="btn-row" style="margin-top:16px"><button class="btn" data-action="copy-script">${tr('copy')}</button><button class="btn outline" data-page="resume">${tr('edit')} ↗</button></div></div><div class="card"><h2>${tr('videoStructure')}</h2><div class="steps" style="margin-top:15px">${[1,2,3,4].map(n=>`<div class="step"><span class="step-num">${n}</span><div><h3>${tr('v'+n)}</h3><p>${tr('v'+n+'s')}</p></div></div>`).join('')}</div><div class="notice warning" style="margin-top:20px">${tr('videoTip')}</div></div></div>${foot()}`}
const cityList=[['160','Алматы'],['159','Астана'],['205','Шымкент'],['177','Қарағанды'],['40','Қазақстан']];
const knownSkills=['Python','SQL','Excel','Power BI','Tableau','Git','JavaScript','TypeScript','React','Figma','PostgreSQL','Django','FastAPI','Docker','Java','PHP','1C','Photoshop'];
const countSkills=jobs=>knownSkills.map(skill=>({name:skill,count:jobs.filter(job=>new RegExp('(^|[^a-z0-9])'+skill.replace(/[-/\\^$*+?.()|[\]{}]/g,'\\$&')+'(?=$|[^a-z0-9])','i').test(`${job.title} ${job.requirements}`)).length})).filter(v=>v.count>0).sort((a,b)=>b.count-a.count).slice(0,9);

