function localRuleReport(a){
 const observations=[];
 if(!a.sampleSize)observations.push(tr('agentRuleNoJobs'));
 else if(!a.matchedSkills.length)observations.push(tr('agentRuleNoTerms'));
 else observations.push(fmt('agentRuleFound',{total:a.sampleSize,n:a.matchedSkills.length}));
 if(a.overlaps?.length)observations.push(fmt('agentRuleOverlap',{names:a.overlaps.map(x=>x.name).join(', ')}));
 if(a.possibleGaps?.length)observations.push(fmt('agentRuleMissing',{names:a.possibleGaps.slice(0,3).map(x=>x.name).join(', ')}));
 return {type:'rule_based',findings:observations,nextSteps:['agentRuleStep1','agentRuleStep2','agentRuleStep3'].map(tr),limitation:tr('agentRuleLimit')}
}

const OFFLINE_TERMS=[
 ['Python',['python','питон']],['SQL',['sql']],['Excel',['excel','эксель']],
 ['Power BI',['power bi','powerbi']],['Tableau',['tableau']],['Git',['git','github']],
 ['REST API',['rest api','rest-api']],['Data analysis',['деректерді талдау','анализ данных','data analysis']],
 ['JavaScript',['javascript']],['React',['react']],['Figma',['figma']]
];
function localSkillMentions(text){
 const lower=String(text||'').toLowerCase();
 return OFFLINE_TERMS.filter(([name,aliases])=>aliases.some(word=>{
  const escaped=word; // Known fixed alias list (no regex metacharacters).
  return new RegExp(`(?<![\\p{L}\\p{N}])${escaped}(?![\\p{L}\\p{N}])`,'iu').test(lower);
 })).map(([name])=>name);
}
function localDatasetAnalysis(sourceData, opts={}){
 if(!sourceData || !Array.isArray(sourceData.vacancies)||sourceData.vacancies.length<2||sourceData.vacancies.length>30) throw Error('DATASET_INVALID');
 const vacancies=sourceData.vacancies.map((v,i)=>{
  if(typeof v?.title!=='string'||v.title.trim().length<3||typeof v?.requirements!=='string'||v.requirements.trim().length<12)throw Error('DATASET_INVALID');
  return {id:`local-${i+1}`,title:v.title.slice(0,160),requirements:v.requirements.slice(0,1200),employer:String(v.employer||'').slice(0,120),link:null,salary:null,publishedAt:null};
 });
 const counts=new Map();
 for(const v of vacancies)for(const name of localSkillMentions(`${v.title} ${v.requirements}`))counts.set(name,(counts.get(name)||0)+1);
 const matchedSkills=[...counts.entries()].map(([name,count])=>({name,count})).sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name));
 const existing=opts.shareSkills?localSkillMentions(S.profile.skills):[];
 const analysis={sampleSize:vacancies.length,profileCompared:existing.length>0,matchedSkills,profileSkillsRecognized:existing,
   overlaps:matchedSkills.filter(v=>existing.includes(v.name)).slice(0,6),possibleGaps:matchedSkills.filter(v=>!existing.includes(v.name)).slice(0,6),
   jobsWithPublishedSalary:0,method:'Local keyword count in user-provided fictional data. Not AI and not a market survey.'};
 return {sampleKind:sourceData.synthetic?'synthetic':'imported',source:sourceData.synthetic?'SYNTHETIC TEST DATA (not real vacancies)':String(sourceData.source||'User-supplied data').slice(0,120),
   sourceUrl:null,found:null,query:'Classroom demo',sampleSize:vacancies.length,vacancies,analysis,report:localRuleReport(analysis),
   aiNarrative:null,aiStatus:'not_requested',model:null,fetchedAt:new Date().toISOString(),collectedAt:null,offlineRules:true,
   note:'Offline classroom analysis only; data unverified and not a sample of the real labor market.'};
}
