 const report=r.findings.map(x=>`<div class="step"><div class="step-num">✓</div><p>${esc(x)}</p></div>`).join('');
 const action=r.nextSteps.map((x,i)=>`<div class="step"><span class="step-num">${i+1}</span><p>${esc(x)}</p></div>`).join('');
