function clearDraft() {
 draftRequest?.abort();
 draftRequest=null;
 cvDraft=null;
 draftError='';
 draftConsent=false;
 draftReview=false;
 draftBusy=false;
 draftLang=null;
 draftReplacements.clear();
}

async function generateDraft() {
 if (draftBusy || chatBusy) return;
 if (!draftConsent) {
  draftError='CONSENT_REQUIRED';
  renderPage();
  return;
 }
 const messages=S.messages.filter(message=>message.role==='user').slice(-10).map(message=>message.content);
 const lang=draftLang||S.cvLang||S.lang;
 cvDraft=null;
 const request=new AbortController();
 draftRequest=request;
 draftBusy=true;
 draftError='';
 draftConsent=false;
 draftReview=false;
 draftReplacements.clear();
 renderPage();
 try {
  const response=await fetch('/api/cv-draft',{
   method:'POST', headers:apiHeaders({'Content-Type':'application/json'}), signal:request.signal,
   body:JSON.stringify({consent:true,messages,lang})
  });
  const data=await response.json();
  if (!response.ok || !data.draft) throw Error(data.code||'CV_DRAFT_INVALID');
  if (!request.signal.aborted) cvDraft=data;
 } catch (error) {
  if (!request.signal.aborted) draftError=error instanceof TypeError?'AI_NETWORK':error.message;
 } finally {
  if (draftRequest===request) {
   draftRequest=null;
   draftBusy=false;
   if (S.page==='assistant') renderPage();
  }
 }
}

function importDraft() {
 if (!cvDraft || !draftReview) return;
 for (const [source,field] of draftEntries()) {
  if (!isDraftConflict(source,field) || draftReplacements.has(field)) {
   S.profile[field]=cvDraft.draft[source];
  }
 }
 S.cvLang=cvDraft.lang;
 clearDraft();
 navigate('resume');
 notify(tr('draftSaved'));
}

function chatMessages(){
 const messages=pendingChat?[...S.messages,pendingChat]:S.messages;
 const bubbles=messages.map(x=>x.role==='user'
  ? `<div class="bubble user">${esc(x.content)}</div>`
  : `<div class="bubble bot">${assistantMarkdown(x.content)}</div>`).join('');
 const pending=chatBusy?`<div class="bubble bot" role="status"><span class="spinner" aria-hidden="true"></span> ${tr('chatSending')}</div>`:'';
 const failure=failedChat?`<div class="bubble bot"><p role="alert">${esc(apiError(failedChat.code))}</p>
  <button class="btn small soft" data-action="retry-chat">${tr('chatRetry')}</button></div>`:'';
 return `<div class="bubble bot">${tr('chatHello')}</div>${bubbles}${pending}${failure}`;
}
