async function importBackup(file){
 if(!file||file.size>100_000)return notify(tr('backupInvalid'));
 try{
  const data=JSON.parse(await file.text());
  if(data?.kind!=='careerbrand-ai-backup'||data?.version!==5||!data.profile||!Array.isArray(data.projects)||!data.meta||data.projects.length>35)throw Error('Invalid backup');
  if(!confirm(tr('backupConfirm')))return;
  const original=blank();const keys=Object.keys(original.profile);const profile=Object.fromEntries(keys.map(k=>[k,typeof data.profile[k]==='string'?data.profile[k].slice(0,2500):'']));
  const meta=Object.fromEntries(Object.keys(original.meta).map(k=>[k,typeof data.meta[k]==='string'?data.meta[k].slice(0,140):'']));
  const projects=data.projects.map(x=>({name:typeof x?.name==='string'?x.name.slice(0,140):'',desc:typeof x?.desc==='string'?x.desc.slice(0,1500):'',link:typeof x?.link==='string'&&/^https?:\/\//.test(x.link)?x.link.slice(0,500):''})).filter(x=>x.name&&x.desc);
  clearChat();
  S={...original,profile,projects,meta,lang:['kk','ru','en'].includes(data.lang)?data.lang:'kk',cvLang:['kk','ru','en'].includes(data.cvLang)?data.cvLang:null};editingProjectId=-1;cvReview=null;cvReviewConsent=false;serviceCheck=null;
  save();document.documentElement.lang=S.lang;shell();notify(tr('backupImported'));
 }catch{notify(tr('backupInvalid'))}
}
const PAGE_PATH={overview:'/',brand:'/brand',resume:'/cv',portfolio:'/portfolio',video:'/video',market:'/market',assistant:'/assistant',research:'/research',media:'/media'};
const PATH_PAGE=Object.fromEntries(Object.entries(PAGE_PATH).map(([k,v])=>[v,k]));
if(typeof window !== 'undefined' && window.location && PATH_PAGE[window.location.pathname])S.page=PATH_PAGE[window.location.pathname];
if(typeof window !== 'undefined' && typeof window.addEventListener === 'function')window.addEventListener('popstate',()=>{S.page=PATH_PAGE[window.location.pathname]||'overview';save();shell();window.scrollTo(0,0)});
function navigate(page){S.page=page;if(typeof window !== 'undefined' && window.history && window.location && /^https?:$/.test(window.location.protocol) && window.location.pathname!==PAGE_PATH[page])window.history.pushState({},'',PAGE_PATH[page]);save();shell();if(typeof window!=='undefined'&&window.scrollTo)window.scrollTo(0,0)}
const sections={overview,brand,resume,portfolio,video,market,assistant,research,media};
function renderPage(){const content=document.getElementById('content');if(content){content.innerHTML=sections[S.page]();if(S.page==='assistant'){const chat=document.getElementById('chat-body');if(chat)chat.scrollTop=chat.scrollHeight;}}}
function notify(text){let prev=document.querySelector('.toast');if(prev)prev.remove();const x=document.createElement('div');x.className='toast';x.role='status';x.textContent=text;document.body.append(x);setTimeout(()=>x.remove(),3200)}
