async function getJobs(){const input=document.getElementById('job-query'),sel=document.getElementById('job-city');let q=input?.value.trim()||'';if(q.length<2){notify(tr('required'));return}S.marketParams={query:q.slice(0,75),area:sel.value};marketBusy=true;renderPage();try{const resp=await fetch(`/api/jobs?query=${encodeURIComponent(q)}&area=${encodeURIComponent(S.marketParams.area)}`,{headers:apiHeaders()});const d=await resp.json();if(!resp.ok||!Array.isArray(d.vacancies))throw Error(d.code||'no-data');S.market=d;marketError='';save()}catch(e){S.market=null;marketError=e.message;notify(apiError(e.message))}finally{marketBusy=false;renderPage()}}
async function importDataset(file){
 if(!file)return;
 if(file.size>30000){notify(tr('importTooLarge'));return}
 const aiConsent=document.getElementById('dataset-ai-consent')?.checked===true;
 agentBusy=true;renderPage();
 try{
  const parsed=JSON.parse(await file.text());
  if(!parsed||!Array.isArray(parsed.vacancies)||parsed.vacancies.length<2||parsed.vacancies.length>30)throw Error('DATASET_INVALID');
  for(const v of parsed.vacancies)if(typeof v?.title!=='string'||typeof v?.requirements!=='string'||v.title.trim().length<3||v.requirements.trim().length<12)throw Error('DATASET_INVALID');
  if(typeof location!=='undefined'&&location.protocol==='file:'&&aiConsent!==true){S.market=localDatasetAnalysis(parsed,{shareSkills:S.shareAgentSkills});marketError='';save();notify(tr('importSuccess'));return;}
  const r=await fetch('/api/analyze-dataset',{method:'POST',headers:apiHeaders({'Content-Type':'application/json'}),body:JSON.stringify({lang:S.lang,query:S.marketParams.query,source:String(parsed.source||'').slice(0,120),collectedAt:parsed.collectedAt,synthetic:parsed.synthetic===true,vacancies:parsed.vacancies,shareSkills:S.shareAgentSkills,profile:S.shareAgentSkills?{skills:S.profile.skills}:{},useAI:aiConsent,aiConsent})});
  const d=await r.json();
  if(!r.ok||!d.analysis||!d.report||!Array.isArray(d.vacancies))throw Error(d.code||'DATASET_INVALID');
  S.market=d;marketError='';save();notify(tr('importSuccess'));
 }catch(e){marketError=e.message==='DATASET_INVALID'?'DATASET_INVALID':e.message||'DATASET_INVALID';notify(tr('importError'))}
 finally{agentBusy=false;renderPage()}
}
async function getAgent(){
 const input=document.getElementById('job-query'), sel=document.getElementById('job-city');
 const query=(input?.value||'').trim();
 if(query.length<2){notify(tr('required'));return}
 S.marketParams={query:query.slice(0,75),area:sel.value};
 agentBusy=true;renderPage();
 try{
  const response=await fetch('/api/agent',{method:'POST',headers:apiHeaders({'Content-Type':'application/json'}),
   body:JSON.stringify({lang:S.lang,query:S.marketParams.query,area:S.marketParams.area,
    profile:S.shareAgentSkills?{skills:S.profile.skills}:{},useAI:true})});
  const data=await response.json();
  if(!response.ok||!Array.isArray(data.vacancies)||!data.analysis||!data.report)throw Error(data.code||'NO_RESULT');
  S.market=data;marketError='';save();
 }catch(e){S.market=null;marketError=e.message;notify(apiError(e.message))}
 finally{agentBusy=false;renderPage()}
}
async function sendChat(retry=false){
 if(chatBusy)return;
 const el=document.getElementById('chat-input');
 const txt=(retry?failedChat?.text:el?.value??chatDraft)?.trim();
 if(!txt)return;
 const lang=S.lang;
 const request=new AbortController();
 chatRequest=request;
 pendingChat={role:'user',content:txt};
 const messages=[...S.messages.filter(m=>!m.aiError),pendingChat].slice(-10);
 if(!retry||chatDraft===txt)updateChatDraft('');
 failedChat=null;
 chatBusy=true;
 updateChat();
 try{
  const r=await fetch('/api/chat',{
   method:'POST',headers:apiHeaders({'Content-Type':'application/json'}),signal:request.signal,
   body:JSON.stringify({lang,shareProfile:S.shareChatProfile,profile:S.shareChatProfile?S.profile:{},messages,market:S.market?.vacancies?.slice(0,5)||[]})
  });
  const d=await r.json();
  if(!r.ok||!d.reply)throw Error(d.code||'AI_UPSTREAM');
  if(request.signal.aborted)return;
  S.messages=[...S.messages.filter(m=>!m.aiError),pendingChat,{role:'assistant',content:String(d.reply).slice(0,4000)}].slice(-20);
  save();
 }catch(err){
  if(request.signal.aborted)return;
  failedChat={text:txt,code:err instanceof TypeError?'AI_NETWORK':err.message};
  if(!chatDraft)updateChatDraft(txt);
 }finally{
  if(chatRequest===request){
   chatRequest=null;
   pendingChat=null;
   chatBusy=false;
   updateChat();
  }
 }
}

function updateChat(){
 const body=document.getElementById('chat-body');
 if(!body)return;
 body.innerHTML=chatMessages();
 body.scrollTop=body.scrollHeight;
 const input=document.getElementById('chat-input');
 if(input&&input.value!==chatDraft)input.value=chatDraft;
 for(const button of document.querySelectorAll('#chat-form button,[data-action="generate-draft"]')){
  button.disabled=chatBusy||(button.dataset.action==='generate-draft'&&draftBusy);
 }
}

function clearChat(){
 chatRequest?.abort();
 chatRequest=null;
 pendingChat=null;
 failedChat=null;
 chatBusy=false;
 updateChatDraft('');
 S.messages=[];
 clearDraft();
 save();
}
